script:
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
cd "$env:USERPROFILE\Desktop\audit2"
"=== checking opencode auth status ==="
try {
  opencode auth list 2>&1 | Select-Object -First 10
} catch {
  "auth list failed: " + $_.Exception.Message
}
"=== checking available models ==="
try {
  opencode models 2>&1 | Select-Object -First 20
} catch {
  "models list failed"
}
